using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.IntegrationTest.Architecture;

public sealed class LayerDependencyTests
{
    private const string Root = "PaymentAuthorization";

    // Pure language core only: no I/O, network, persistence, reflection, process or environment access.
    private static readonly HashSet<string> CoreNamespaces =
    [
        "System",
        "System.Collections",
        "System.Collections.Generic",
        "System.Collections.Immutable",
        "System.Linq",
        "System.Threading",
        "System.Threading.Tasks",
        "System.Runtime.CompilerServices",
        "System.Diagnostics.CodeAnalysis",
    ];

    // Types in the allowed "System" namespace that still reach technical resources.
    private static readonly HashSet<string> ForbiddenCoreTypes =
    [
        "System.Console",
        "System.Environment",
        "System.Activator",
        "System.AppDomain",
        "System.GC",
        "System.Random",
    ];

    private static readonly Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly Assembly ApplicationAssembly = typeof(AuthorizePayment).Assembly;

    [Fact]
    public void Domain_depends_only_on_itself_and_the_language_core()
        => AssertOnlyDependsOn(DomainAssembly, allowedBusinessAssemblies: []);

    [Fact]
    public void Application_depends_only_on_itself_Domain_and_the_language_core()
        => AssertOnlyDependsOn(ApplicationAssembly, allowedBusinessAssemblies: [DomainAssembly.GetName().Name!]);

    private static void AssertOnlyDependsOn(Assembly assembly, string[] allowedBusinessAssemblies)
    {
        var self = assembly.GetName().Name!;
        var violations = new List<string>();

        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var md = pe.GetMetadataReader();

        foreach (var handle in md.AssemblyReferences)
        {
            var name = md.GetString(md.GetAssemblyReference(handle).Name);
            if (name.StartsWith(Root, StringComparison.Ordinal) && name != self && !allowedBusinessAssemblies.Contains(name))
                violations.Add($"assembly reference '{name}'");
        }

        foreach (var handle in md.TypeReferences)
        {
            var type = md.GetTypeReference(handle);
            var ns = md.GetString(type.Namespace);
            var full = ns.Length == 0 ? md.GetString(type.Name) : $"{ns}.{md.GetString(type.Name)}";

            if (ns == self || allowedBusinessAssemblies.Contains(ns)) continue;
            if (CoreNamespaces.Contains(ns) && !ForbiddenCoreTypes.Contains(full)) continue;
            violations.Add($"type '{full}'");
        }

        Assert.True(violations.Count == 0, $"{self} has forbidden dependencies. Violations: {string.Join(", ", violations.Distinct().Order())}");
    }
}
EOF
